Document:
{%- macro address(a) %}
{%- if a %}

	{%- if a.street_name %}
	{{a.street_name}}
	{%- endif %}
	{%- if a.building_number %}
	{{a.building_number}}
	{%- endif %}
	{%- if a.postal_code %}
	{{a.postal_code}}
	{%- endif %}
	{%- if a.town_name %}
	{{a.town_name}}
	{%- endif %}
	{%- if a.country_subdivision %}
	{{a.country_subdivision}}
	{%- endif %}
	{%- if a.country_code %}
	{{a.country_code}}
	{%- endif %}
	{%- if a.address_line %}
	{{a.address_line}}
	{%- endif %}

{%- endif %}
{%- endmacro %}
{%- macro party_id(p) %}
{%- if p.lei or p.id %}


		{%- if p.lei %}
		{{p.lei}}
		{%- endif %}
		{%- if p.id %}

			{{p.id}}
			{%- if p.id_scheme %}

				{{p.id_scheme}}

			{%- elif p.id_scheme_proprietary %}

				{{p.id_scheme_proprietary}}

			{%- endif %}

		{%- endif %}


{%- endif %}
{%- endmacro %}
{%- macro agent(g) %}

	{%- if g.bic %}
	{{g.bic}}
	{%- endif %}
	{%- if g.member_id %}

		{%- if g.clearing_system %}

			{{g.clearing_system}}

		{%- endif %}
		{{g.member_id}}

	{%- endif %}
	{%- if g.name %}
	{{g.name}}
	{%- endif %}
	{%- if g.address %}

		{%- if g.address.town_name %}
		{{g.address.town_name}}
		{%- endif %}
		{%- if g.address.country_subdivision %}
		{{g.address.country_subdivision}}
		{%- endif %}
		{%- if g.address.country_code %}
		{{g.address.country_code}}
		{%- endif %}

	{%- endif %}

{%- endmacro %}
{%- macro account(c) %}

	{%- if c.iban %}
	{{c.iban}}
	{%- else %}

		{{c.number}}
		{%- if c.scheme %}

			{{c.scheme}}

		{%- elif c.scheme_proprietary %}

			{{c.scheme_proprietary}}

		{%- endif %}

	{%- endif %}

{%- if c.currency %}
{{c.currency}}
{%- endif %}
{%- endmacro %}


		{{id}}
		{{date}}
		{{nb_of_txs}}
		{{ctrl_sum}}

			{{initiator_name}}
			{{- address(initiator_address) | indent('\t\t\t') }}
			{{- party_id(initiator) | indent('\t\t\t') }}



		{{payment_information_id}}
		{{payment_method}}
		{%- if batch_booking is not none %}
		{{batch_booking}}
		{%- endif %}
		{{nb_of_txs}}
		{{ctrl_sum}}
		{%- if payment_type %}

			{%- if payment_type.instruction_priority %}
			{{payment_type.instruction_priority}}
			{%- endif %}
			{%- if payment_type.service_level_code %}

				{{payment_type.service_level_code}}

			{%- endif %}
			{%- if payment_type.local_instrument_code %}

				{{payment_type.local_instrument_code}}

			{%- elif payment_type.local_instrument_proprietary %}

				{{payment_type.local_instrument_proprietary}}

			{%- endif %}
			{%- if payment_type.category_purpose_code %}

				{{payment_type.category_purpose_code}}

			{%- endif %}

		{%- endif %}

			{%- if requested_execution_datetime %}
			{{requested_execution_datetime}}
			{%- else %}
			{{requested_execution_date}}
			{%- endif %}


			{{debtor_name}}
			{{- address(debtor_address) | indent('\t\t\t') }}
			{{- party_id(debtor) | indent('\t\t\t') }}


			{{- account(debtor_account) | indent('\t\t\t') }}


			{{- agent(debtor_agent) | indent('\t\t\t') }}

		{%- if ultimate_debtor_name %}

			{{ultimate_debtor_name}}

		{%- endif %}
		{{charge_bearer}}
		{%- for tx in transactions %}


				{%- if tx.instruction_id %}
				{{tx.instruction_id}}
				{%- endif %}
				{{tx.payment_id}}
				{%- if tx.uetr %}
				{{tx.uetr}}
				{%- endif %}


				{{tx.payment_amount}}


				{{- agent(tx.creditor_agent) | indent('\t\t\t\t') }}


				{{tx.creditor_name}}
				{{- address(tx.creditor_address) | indent('\t\t\t\t') }}


				{{- account(tx.creditor_account) | indent('\t\t\t\t') }}

			{%- if tx.ultimate_creditor_name %}

				{{tx.ultimate_creditor_name}}

			{%- endif %}
			{%- if tx.purpose_code %}

				{{tx.purpose_code}}

			{%- endif %}
			{%- if tx.regulatory %}

				{{tx.regulatory.indicator or "CRED"}}

					{%- if tx.regulatory.country %}
					{{tx.regulatory.country}}
					{%- endif %}
					{%- if tx.regulatory.code %}
					{{tx.regulatory.code}}
					{%- endif %}
					{%- if tx.regulatory.info %}
					{{tx.regulatory.info}}
					{%- endif %}


			{%- endif %}
			{%- if tx.remittance_information or tx.creditor_reference %}

				{%- if tx.remittance_information %}
				{{tx.remittance_information}}
				{%- endif %}
				{%- if tx.creditor_reference %}


						{%- if tx.creditor_reference_type %}


								{%- if tx.creditor_reference_is_code %}
								{{tx.creditor_reference_type}}
								{%- else %}
								{{tx.creditor_reference_type}}
								{%- endif %}

							{%- if tx.creditor_reference_issuer %}
							{{tx.creditor_reference_issuer}}
							{%- endif %}

						{%- endif %}
						{{tx.creditor_reference}}

					{%- if tx.additional_remittance_information %}
					{{tx.additional_remittance_information}}
					{%- endif %}

				{%- endif %}

			{%- endif %}
			{%- if tx.supplementary_data %}


					{{tx.supplementary_data}}


			{%- endif %}

		{%- endfor %}
